-- Reported structural schema; only sequence defaults modeled.
CREATE TABLE recurring_blocked_times ("id" serial NOT NULL PRIMARY KEY,"employee_id" integer NOT NULL,"start_time" time without time zone NOT NULL,"end_time" time without time zone NOT NULL,"frequency" text NOT NULL,"day_of_week" integer,"reason" text,"num_occurrences" integer,"is_deleted" boolean,"created_at" timestamp with time zone,"type" text);
CREATE TABLE email_logs ("id" serial NOT NULL PRIMARY KEY,"tenant_id" integer,"appointment_id" integer,"recipient_email" text NOT NULL,"recipient_name" text,"subject" text NOT NULL,"body" text NOT NULL,"sent_at" timestamp with time zone,"status" text,"error_message" text,"email_type" text,"metadata" jsonb);
CREATE TABLE sms_messages ("id" serial NOT NULL PRIMARY KEY,"tenant_id" integer,"appointment_id" integer,"client_id" integer,"direction" text NOT NULL,"phone" text NOT NULL,"message" text NOT NULL,"sender_name" text,"sent_at" timestamp with time zone,"read_at" timestamp with time zone,"provider" text,"metadata" jsonb,"created_at" timestamp with time zone,"conversation_id" integer,"is_urgent" boolean,"segment_count" integer);
